-- P08/P12 contracts and missions: immutable versions, signatures, evidence and governed transitions.

create table public.contracts (
  id uuid primary key default extensions.gen_random_uuid(),
  client_organization_id uuid not null references public.organizations(id) on delete restrict,
  provider_organization_id uuid not null references public.organizations(id) on delete restrict,
  status text not null default 'DRAFT' check(status in('DRAFT','PENDING_SIGNATURE','ACTIVE','AMENDED','COMPLETED','TERMINATED')),
  current_version integer not null default 1 check(current_version>0),
  created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),row_version integer not null default 1 check(row_version>0),
  check(client_organization_id<>provider_organization_id)
);
create table public.contract_versions (
  id uuid primary key default extensions.gen_random_uuid(),contract_id uuid not null references public.contracts(id) on delete restrict,
  version integer not null check(version>0),selected_quote_version_id uuid not null references public.quote_versions(id) on delete restrict,request_snapshot jsonb not null check(jsonb_typeof(request_snapshot)='object'),quote_snapshot jsonb not null check(jsonb_typeof(quote_snapshot)='object'),
  clauses jsonb not null check(jsonb_typeof(clauses)='object'),price_minor bigint not null check(price_minor>=0),currency char(3) not null check(currency~'^[A-Z]{3}$'),
  commission_rule_snapshot jsonb not null check(jsonb_typeof(commission_rule_snapshot)='object'),content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),
  change_reason text not null check(length(btrim(change_reason)) between 3 and 1000),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(contract_id,version),unique(id,contract_id)
);
create table public.contract_parties(contract_version_id uuid not null references public.contract_versions(id) on delete restrict,organization_id uuid not null references public.organizations(id) on delete restrict,party_role text not null check(party_role in('CLIENT','PROVIDER')),legal_snapshot jsonb not null check(jsonb_typeof(legal_snapshot)='object'),primary key(contract_version_id,party_role),unique(contract_version_id,organization_id));
create table public.contract_items(id uuid primary key default extensions.gen_random_uuid(),contract_version_id uuid not null references public.contract_versions(id) on delete restrict,item_key text not null check(item_key~'^[A-Z][A-Z0-9_-]{1,79}$'),item_type text not null check(item_type in('DELIVERABLE','EXCLUSION','ACCEPTANCE_CRITERION','PAYMENT_TERM','CORRECTION','PENALTY')),label_fr text not null check(length(btrim(label_fr)) between 1 and 500),label_ar text not null check(length(btrim(label_ar)) between 1 and 500),details jsonb not null default '{}' check(jsonb_typeof(details)='object'),sort_order integer not null check(sort_order>0),unique(contract_version_id,item_key));
create table public.contract_signatures(id uuid primary key default extensions.gen_random_uuid(),contract_id uuid not null,contract_version_id uuid not null,organization_id uuid not null references public.organizations(id) on delete restrict,signer_user_id uuid not null references auth.users(id),signer_role text not null,contract_hash text not null check(contract_hash~'^[0-9a-f]{64}$'),proof jsonb not null check(jsonb_typeof(proof)='object' and proof?&array['method','signed_at','evidence_hash'] and proof->>'evidence_hash'~'^[0-9a-f]{64}$'),signed_at timestamptz not null default clock_timestamp(),correlation_id uuid not null,foreign key(contract_version_id,contract_id) references public.contract_versions(id,contract_id) on delete restrict,unique(contract_version_id,organization_id));
create table public.change_requests(id uuid primary key default extensions.gen_random_uuid(),contract_id uuid not null references public.contracts(id) on delete restrict,requested_by uuid not null references auth.users(id),status text not null default 'REQUESTED' check(status in('REQUESTED','ACCEPTED','REJECTED','SUPERSEDED')),reason text not null check(length(btrim(reason)) between 3 and 2000),scope_delta jsonb not null check(jsonb_typeof(scope_delta)='object'),created_at timestamptz not null default now(),decided_at timestamptz);
create table public.contract_amendments(id uuid primary key default extensions.gen_random_uuid(),contract_id uuid not null references public.contracts(id) on delete restrict,change_request_id uuid not null unique references public.change_requests(id) on delete restrict,base_contract_version_id uuid not null references public.contract_versions(id) on delete restrict,amendment_number integer not null check(amendment_number>0),status text not null default 'DRAFT' check(status in('DRAFT','PENDING_SIGNATURE','ACTIVE','REJECTED','SUPERSEDED')),price_delta_minor bigint not null,deadline_delta_days integer not null,deliverables_delta jsonb not null check(jsonb_typeof(deliverables_delta)='array'),commission_rule_snapshot jsonb not null check(jsonb_typeof(commission_rule_snapshot)='object'),content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(contract_id,amendment_number));

create table public.missions(id uuid primary key default extensions.gen_random_uuid(),contract_id uuid not null references public.contracts(id) on delete restrict,contract_version_id uuid not null references public.contract_versions(id) on delete restrict,client_organization_id uuid not null references public.organizations(id) on delete restrict,provider_organization_id uuid not null references public.organizations(id) on delete restrict,status text not null default 'PLANNED' check(status in('PLANNED','ACTIVE','DELIVERY_SUBMITTED','ACCEPTANCE_IN_PROGRESS','COMPLETED','CANCELLED')),started_at timestamptz,completed_at timestamptz,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),row_version integer not null default 1 check(row_version>0),unique(contract_id),check(client_organization_id<>provider_organization_id),foreign key(contract_version_id,contract_id) references public.contract_versions(id,contract_id) on delete restrict);
create table public.mission_milestones(id uuid primary key default extensions.gen_random_uuid(),mission_id uuid not null references public.missions(id) on delete restrict,milestone_key text not null check(milestone_key~'^[A-Z][A-Z0-9_-]{1,79}$'),title_fr text not null,title_ar text not null,sort_order integer not null check(sort_order>0),due_at timestamptz,owner_organization_id uuid not null references public.organizations(id),validation_required boolean not null default true,status text not null default 'PENDING' check(status in('PENDING','IN_PROGRESS','SUBMITTED','ACCEPTED','REJECTED')),submitted_at timestamptz,decided_at timestamptz,row_version integer not null default 1 check(row_version>0),unique(mission_id,milestone_key),unique(mission_id,sort_order));
create table public.service_checklist_templates(id uuid primary key default extensions.gen_random_uuid(),service_version_id uuid not null references public.catalog_service_versions(id) on delete restrict,version integer not null check(version>0),items jsonb not null check(jsonb_typeof(items)='array'),content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(service_version_id,version));
create table public.mission_checklist_items(id uuid primary key default extensions.gen_random_uuid(),mission_id uuid not null references public.missions(id) on delete restrict,milestone_id uuid references public.mission_milestones(id) on delete restrict,item_key text not null,label_fr text not null,label_ar text not null,proof_required boolean not null default false,status text not null default 'PENDING' check(status in('PENDING','COMPLETED','WAIVED')),completed_by uuid references auth.users(id),completed_at timestamptz,unique(mission_id,item_key));
create table public.deliverables(id uuid primary key default extensions.gen_random_uuid(),mission_id uuid not null references public.missions(id) on delete restrict,milestone_id uuid references public.mission_milestones(id) on delete restrict,deliverable_key text not null,label_fr text not null,label_ar text not null,proof_required boolean not null default true,current_version integer not null default 0 check(current_version>=0),status text not null default 'PENDING' check(status in('PENDING','SUBMITTED','ACCEPTED','REJECTED')),unique(mission_id,deliverable_key));
create table public.delivery_versions(id uuid primary key default extensions.gen_random_uuid(),deliverable_id uuid not null references public.deliverables(id) on delete restrict,version integer not null check(version>0),description text not null check(length(btrim(description)) between 3 and 4000),links jsonb not null default '[]' check(jsonb_typeof(links)='array'),content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),submitted_by uuid not null references auth.users(id),submitted_at timestamptz not null default clock_timestamp(),unique(deliverable_id,version));
create table public.delivery_proofs(id uuid primary key default extensions.gen_random_uuid(),delivery_version_id uuid not null references public.delivery_versions(id) on delete restrict,proof_type text not null check(proof_type in('DOCUMENT','IMAGE','URL','CHECKLIST','OTHER')),storage_path text,url text,evidence_hash text not null check(evidence_hash~'^[0-9a-f]{64}$'),metadata jsonb not null default '{}' check(jsonb_typeof(metadata)='object'),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),check(num_nonnulls(storage_path,url)>=1));
create table public.acceptance_checklists(id uuid primary key default extensions.gen_random_uuid(),mission_id uuid not null references public.missions(id) on delete restrict,deliverable_id uuid not null references public.deliverables(id) on delete restrict,criterion_key text not null,status text not null default 'PENDING' check(status in('PENDING','COMPLIANT','NONCOMPLIANT','NA')),comment text,evidence jsonb not null default '[]' check(jsonb_typeof(evidence)='array'),decided_by uuid references auth.users(id),decided_at timestamptz,unique(deliverable_id,criterion_key));

create function private.contract_party_access(p_contract_id uuid,p_actor uuid default auth.uid()) returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$select exists(select 1 from public.contracts c where c.id=p_contract_id and(private.is_active_org_member(c.client_organization_id,p_actor)or private.is_active_org_member(c.provider_organization_id,p_actor)))or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','READ_ONLY_AUDITOR'],p_actor)$$;
create function private.mission_party_access(p_mission_id uuid,p_actor uuid default auth.uid()) returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$select exists(select 1 from public.missions m where m.id=p_mission_id and(private.is_active_org_member(m.client_organization_id,p_actor)or private.is_active_org_member(m.provider_organization_id,p_actor)))or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','READ_ONLY_AUDITOR'],p_actor)$$;
create function private.prevent_contract_immutable_change() returns trigger language plpgsql set search_path=pg_catalog as $$begin raise exception 'IMMUTABLE_CONTRACT_RECORD' using errcode='55000';end$$;
create function private.bind_selected_quote_version() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$declare c public.contracts%rowtype;begin new.selected_quote_version_id:=nullif(new.quote_snapshot->>'quote_version_id','')::uuid;select * into c from public.contracts where id=new.contract_id;if new.selected_quote_version_id is null or not exists(select 1 from public.quote_versions qv join public.quotes q on q.id=qv.quote_id join public.rfqs r on r.id=q.rfq_id join public.service_requests sr on sr.id=r.request_id where qv.id=new.selected_quote_version_id and q.selected_version_id=qv.id and q.status='SELECTED'and q.provider_organization_id=c.provider_organization_id and sr.client_organization_id=c.client_organization_id and qv.total_minor=new.price_minor and qv.currency=new.currency)then raise exception 'SELECTED_QUOTE_VERSION_REQUIRED' using errcode='22023';end if;return new;end$$;

create trigger contract_versions_bind_selected_quote before insert on public.contract_versions for each row execute function private.bind_selected_quote_version();
create trigger contract_versions_immutable before update or delete on public.contract_versions for each row execute function private.prevent_contract_immutable_change();
create trigger contract_parties_immutable before update or delete on public.contract_parties for each row execute function private.prevent_contract_immutable_change();
create trigger contract_items_immutable before update or delete on public.contract_items for each row execute function private.prevent_contract_immutable_change();
create trigger contract_signatures_immutable before update or delete on public.contract_signatures for each row execute function private.prevent_contract_immutable_change();
create trigger amendments_immutable before update or delete on public.contract_amendments for each row execute function private.prevent_contract_immutable_change();
create trigger delivery_versions_immutable before update or delete on public.delivery_versions for each row execute function private.prevent_contract_immutable_change();
create trigger delivery_proofs_immutable before update or delete on public.delivery_proofs for each row execute function private.prevent_contract_immutable_change();

create function private.begin_contract_command(p_org uuid,p_scope text,p_key text,p_hash text,p_actor uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare v public.idempotency_keys%rowtype;begin if length(coalesce(p_key,''))not between 8 and 200 then raise exception 'INVALID_IDEMPOTENCY_KEY' using errcode='22023';end if;perform pg_advisory_xact_lock(hashtextextended(p_org::text||':'||p_scope||':'||p_key,0));select * into v from public.idempotency_keys where organization_id=p_org and operation_scope=p_scope and key=p_key;if found then if v.request_hash<>p_hash then raise exception 'IDEMPOTENCY_PAYLOAD_MISMATCH' using errcode='22000';end if;if v.status='COMPLETED'then return v.response_body;end if;raise exception 'COMMAND_IN_PROGRESS' using errcode='55000';end if;insert into public.idempotency_keys(organization_id,operation_scope,key,request_hash,created_by,expires_at)values(p_org,p_scope,p_key,p_hash,p_actor,now()+interval'7 days');return null;end$$;
create function private.finish_contract_command(p_org uuid,p_scope text,p_key text,p_response jsonb) returns void language sql security definer set search_path=pg_catalog,public as $$update public.idempotency_keys set status='COMPLETED',response_code=200,response_body=p_response,completed_at=clock_timestamp()where organization_id=p_org and operation_scope=p_scope and key=p_key$$;

create function public.generate_contract(p_client_organization_id uuid,p_provider_organization_id uuid,p_request_snapshot jsonb,p_quote_snapshot jsonb,p_clauses jsonb,p_price_minor bigint,p_currency text,p_commission_rule_snapshot jsonb,p_client_legal_snapshot jsonb,p_provider_legal_snapshot jsonb,p_change_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid()) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();h text;r jsonb;c uuid;v uuid;begin if a is null or not private.has_org_role(p_client_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'],a)then raise exception 'CONTRACT_GENERATE_DENIED' using errcode='42501';end if;if p_client_organization_id=p_provider_organization_id or p_price_minor<0 or p_currency!~'^[A-Z]{3}$'or jsonb_typeof(p_request_snapshot)<>'object'or jsonb_typeof(p_quote_snapshot)<>'object'or jsonb_typeof(p_clauses)<>'object'or jsonb_typeof(p_commission_rule_snapshot)<>'object'or length(btrim(coalesce(p_change_reason,'')))not between 3 and 1000 then raise exception 'INVALID_CONTRACT' using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('client',p_client_organization_id,'provider',p_provider_organization_id,'request',p_request_snapshot,'quote',p_quote_snapshot,'clauses',p_clauses,'price_minor',p_price_minor,'currency',p_currency,'commission',p_commission_rule_snapshot,'client_legal',p_client_legal_snapshot,'provider_legal',p_provider_legal_snapshot));r:=private.begin_contract_command(p_client_organization_id,'contract.generate',p_idempotency_key,h,a);if r is not null then return r;end if;insert into public.contracts(client_organization_id,provider_organization_id,created_by)values(p_client_organization_id,p_provider_organization_id,a)returning id into c;insert into public.contract_versions(contract_id,version,request_snapshot,quote_snapshot,clauses,price_minor,currency,commission_rule_snapshot,content_hash,change_reason,created_by)values(c,1,p_request_snapshot,p_quote_snapshot,p_clauses,p_price_minor,p_currency,p_commission_rule_snapshot,h,p_change_reason,a)returning id into v;insert into public.contract_parties values(v,p_client_organization_id,'CLIENT',p_client_legal_snapshot),(v,p_provider_organization_id,'PROVIDER',p_provider_legal_snapshot);r:=jsonb_build_object('outcome','CONTRACT_GENERATED','contract_id',c,'contract_version_id',v,'version',1,'content_hash',h);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_client_organization_id,a,'USER','contract.generated','contract',c::text,p_correlation_id,jsonb_build_object('version_id',v,'provider_organization_id',p_provider_organization_id),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_client_organization_id,'contract',c::text,'ContractGeneratedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p_client_organization_id,'contract.generate',p_idempotency_key,r);return r;end$$;

create function public.submit_contract_for_signature(p_contract_id uuid,p_expected_row_version integer,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();c public.contracts%rowtype;h text;r jsonb;begin select * into c from public.contracts where id=p_contract_id;if a is null or not found or not private.has_org_role(c.client_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'],a)then raise exception 'CONTRACT_SUBMIT_DENIED' using errcode='42501';end if;h:=private.canonical_request_hash(jsonb_build_object('contract_id',p_contract_id,'expected',p_expected_row_version));r:=private.begin_contract_command(c.client_organization_id,'contract.submit',p_idempotency_key,h,a);if r is not null then return r;end if;select * into c from public.contracts where id=p_contract_id for update;if c.status<>'DRAFT'or c.row_version<>p_expected_row_version then raise exception 'INVALID_CONTRACT_TRANSITION' using errcode='55000';end if;update public.contracts set status='PENDING_SIGNATURE',row_version=row_version+1,updated_at=now()where id=c.id;r:=jsonb_build_object('outcome','CONTRACT_PENDING_SIGNATURE','contract_id',c.id,'row_version',c.row_version+1);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(c.client_organization_id,a,'USER','contract.submitted','contract',c.id::text,p_correlation_id,'{}',repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(c.client_organization_id,'contract',c.id::text,'ContractSignatureRequestedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(c.client_organization_id,'contract.submit',p_idempotency_key,r);return r;end$$;

create function public.sign_contract(p_contract_id uuid,p_contract_version_id uuid,p_organization_id uuid,p_expected_contract_hash text,p_signer_role text,p_proof jsonb,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();c public.contracts%rowtype;v public.contract_versions%rowtype;h text;r jsonb;s uuid;n integer;begin select * into c from public.contracts where id=p_contract_id;if a is null or not found or c.status<>'PENDING_SIGNATURE'or p_organization_id not in(c.client_organization_id,c.provider_organization_id)or not private.has_org_role(p_organization_id,case when p_organization_id=c.client_organization_id then array['CLIENT_OWNER','CLIENT_ADMIN']else array['PROVIDER_OWNER']end,a)then raise exception 'CONTRACT_SIGN_DENIED' using errcode='42501';end if;select * into v from public.contract_versions where id=p_contract_version_id and contract_id=c.id and version=c.current_version;if not found or v.content_hash<>p_expected_contract_hash then raise exception 'STALE_CONTRACT_VERSION' using errcode='40001';end if;if jsonb_typeof(p_proof)<>'object'or not(p_proof?&array['method','signed_at','evidence_hash'])then raise exception 'INVALID_SIGNATURE_PROOF' using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('contract',c.id,'version',v.id,'organization',p_organization_id,'hash',p_expected_contract_hash,'role',p_signer_role,'proof',p_proof));r:=private.begin_contract_command(c.client_organization_id,'contract.sign.'||p_organization_id::text,p_idempotency_key,h,a);if r is not null then return r;end if;insert into public.contract_signatures(contract_id,contract_version_id,organization_id,signer_user_id,signer_role,contract_hash,proof,correlation_id)values(c.id,v.id,p_organization_id,a,p_signer_role,v.content_hash,p_proof,p_correlation_id)returning id into s;select count(*)into n from public.contract_signatures where contract_version_id=v.id;if n=2 then update public.contracts set status='ACTIVE',row_version=row_version+1,updated_at=now()where id=c.id;end if;r:=jsonb_build_object('outcome',case when n=2 then'CONTRACT_SIGNED'else'CONTRACT_PARTIALLY_SIGNED'end,'contract_id',c.id,'contract_version_id',v.id,'signature_id',s,'signature_count',n);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(c.client_organization_id,a,'USER','contract.signed','contract',c.id::text,p_correlation_id,jsonb_build_object('version_id',v.id,'signer_organization_id',p_organization_id,'signature_id',s),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(c.client_organization_id,'contract',c.id::text,case when n=2 then'ContractSignedV1'else'ContractPartySignedV1'end,p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(c.client_organization_id,'contract.sign.'||p_organization_id::text,p_idempotency_key,r);return r;end$$;

create function public.create_mission(p_contract_id uuid,p_contract_version_id uuid,p_milestones jsonb,p_deliverables jsonb,p_acceptance_criteria jsonb,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();c public.contracts%rowtype;h text;r jsonb;m uuid;x jsonb;ms uuid;begin select * into c from public.contracts where id=p_contract_id;if a is null or not found or not private.has_org_role(c.client_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'],a)then raise exception 'MISSION_CREATE_DENIED' using errcode='42501';end if;if c.status not in('ACTIVE','AMENDED')or not exists(select 1 from public.contract_versions where id=p_contract_version_id and contract_id=c.id and version=c.current_version)or jsonb_typeof(p_milestones)<>'array'or jsonb_array_length(p_milestones)=0 or jsonb_typeof(p_deliverables)<>'array'or jsonb_array_length(p_deliverables)=0 or jsonb_typeof(p_acceptance_criteria)<>'array'or jsonb_array_length(p_acceptance_criteria)=0 then raise exception 'INVALID_MISSION' using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('contract',c.id,'version',p_contract_version_id,'milestones',p_milestones,'deliverables',p_deliverables,'criteria',p_acceptance_criteria));r:=private.begin_contract_command(c.client_organization_id,'mission.create',p_idempotency_key,h,a);if r is not null then return r;end if;insert into public.missions(contract_id,contract_version_id,client_organization_id,provider_organization_id,status,started_at,created_by)values(c.id,p_contract_version_id,c.client_organization_id,c.provider_organization_id,'ACTIVE',clock_timestamp(),a)returning id into m;for x in select * from jsonb_array_elements(p_milestones)loop insert into public.mission_milestones(mission_id,milestone_key,title_fr,title_ar,sort_order,due_at,owner_organization_id,validation_required)values(m,x->>'key',x->>'title_fr',x->>'title_ar',(x->>'sort_order')::integer,nullif(x->>'due_at','')::timestamptz,coalesce((x->>'owner_organization_id')::uuid,c.provider_organization_id),coalesce((x->>'validation_required')::boolean,true))returning id into ms;end loop;for x in select * from jsonb_array_elements(p_deliverables)loop insert into public.deliverables(mission_id,milestone_id,deliverable_key,label_fr,label_ar,proof_required)values(m,nullif(x->>'milestone_id','')::uuid,x->>'key',x->>'label_fr',x->>'label_ar',coalesce((x->>'proof_required')::boolean,true));end loop;for x in select * from jsonb_array_elements(p_acceptance_criteria)loop insert into public.acceptance_checklists(mission_id,deliverable_id,criterion_key)select m,d.id,x->>'criterion_key'from public.deliverables d where d.mission_id=m and d.deliverable_key=x->>'deliverable_key';end loop;r:=jsonb_build_object('outcome','MISSION_CREATED','mission_id',m,'contract_id',c.id);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(c.client_organization_id,a,'USER','mission.created','mission',m::text,p_correlation_id,jsonb_build_object('contract_id',c.id,'contract_version_id',p_contract_version_id),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(c.client_organization_id,'mission',m::text,'MissionCreatedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(c.client_organization_id,'mission.create',p_idempotency_key,r);return r;end$$;

create function public.submit_delivery(p_deliverable_id uuid,p_description text,p_links jsonb,p_proofs jsonb,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();d public.deliverables%rowtype;m public.missions%rowtype;h text;r jsonb;dv uuid;ver integer;x jsonb;begin select * into d from public.deliverables where id=p_deliverable_id;select * into m from public.missions where id=d.mission_id;if a is null or not found or not private.has_org_role(m.provider_organization_id,array['PROVIDER_OWNER','PROVIDER_MANAGER','PROVIDER_TECHNICIAN'],a)then raise exception 'DELIVERY_SUBMIT_DENIED' using errcode='42501';end if;if m.status not in('ACTIVE','DELIVERY_SUBMITTED')or length(btrim(coalesce(p_description,'')))not between 3 and 4000 or jsonb_typeof(p_links)<>'array'or jsonb_typeof(p_proofs)<>'array'or(d.proof_required and jsonb_array_length(p_proofs)=0)then raise exception 'DELIVERY_PROOF_REQUIRED' using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('deliverable',d.id,'description',p_description,'links',p_links,'proofs',p_proofs));r:=private.begin_contract_command(m.client_organization_id,'delivery.submit.'||d.id::text,p_idempotency_key,h,a);if r is not null then return r;end if;select * into d from public.deliverables where id=d.id for update;ver:=d.current_version+1;insert into public.delivery_versions(deliverable_id,version,description,links,content_hash,submitted_by)values(d.id,ver,p_description,p_links,h,a)returning id into dv;for x in select * from jsonb_array_elements(p_proofs)loop insert into public.delivery_proofs(delivery_version_id,proof_type,storage_path,url,evidence_hash,metadata,created_by)values(dv,x->>'type',nullif(x->>'storage_path',''),nullif(x->>'url',''),x->>'evidence_hash',coalesce(x->'metadata','{}'),a);end loop;update public.deliverables set current_version=ver,status='SUBMITTED'where id=d.id;update public.missions set status='DELIVERY_SUBMITTED',row_version=row_version+1,updated_at=now()where id=m.id;r:=jsonb_build_object('outcome','DELIVERY_SUBMITTED','mission_id',m.id,'deliverable_id',d.id,'delivery_version_id',dv,'version',ver);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(m.client_organization_id,a,'USER','delivery.submitted','deliverable',d.id::text,p_correlation_id,jsonb_build_object('mission_id',m.id,'delivery_version_id',dv,'version',ver),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(m.client_organization_id,'mission',m.id::text,'DeliverySubmittedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(m.client_organization_id,'delivery.submit.'||d.id::text,p_idempotency_key,r);return r;end$$;

create function public.accept_delivery(p_deliverable_id uuid,p_decisions jsonb,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();d public.deliverables%rowtype;m public.missions%rowtype;h text;r jsonb;x jsonb;remaining integer;begin select * into d from public.deliverables where id=p_deliverable_id;select * into m from public.missions where id=d.mission_id;if a is null or not found or not private.has_org_role(m.client_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'],a)then raise exception 'DELIVERY_ACCEPT_DENIED' using errcode='42501';end if;if d.status<>'SUBMITTED'or jsonb_typeof(p_decisions)<>'array'or jsonb_array_length(p_decisions)=0 then raise exception 'INVALID_ACCEPTANCE' using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('deliverable',d.id,'version',d.current_version,'decisions',p_decisions));r:=private.begin_contract_command(m.client_organization_id,'delivery.accept.'||d.id::text,p_idempotency_key,h,a);if r is not null then return r;end if;for x in select * from jsonb_array_elements(p_decisions)loop update public.acceptance_checklists set status=x->>'status',comment=nullif(x->>'comment',''),evidence=coalesce(x->'evidence','[]'),decided_by=a,decided_at=clock_timestamp()where deliverable_id=d.id and criterion_key=x->>'criterion_key'and status='PENDING';if not found then raise exception 'ACCEPTANCE_CRITERION_NOT_FOUND_OR_DECIDED' using errcode='P0002';end if;end loop;select count(*)into remaining from public.acceptance_checklists where deliverable_id=d.id and status='PENDING';if remaining>0 then raise exception 'ACCEPTANCE_INCOMPLETE' using errcode='22023';end if;if exists(select 1 from public.acceptance_checklists where deliverable_id=d.id and status='NONCOMPLIANT')then update public.deliverables set status='REJECTED'where id=d.id;r:=jsonb_build_object('outcome','DELIVERY_REJECTED','mission_id',m.id,'deliverable_id',d.id);else update public.deliverables set status='ACCEPTED'where id=d.id;if not exists(select 1 from public.deliverables where mission_id=m.id and status<>'ACCEPTED')then update public.missions set status='COMPLETED',completed_at=clock_timestamp(),row_version=row_version+1,updated_at=now()where id=m.id;update public.contracts set status='COMPLETED',row_version=row_version+1,updated_at=now()where id=m.contract_id;end if;r:=jsonb_build_object('outcome','DELIVERY_ACCEPTED','mission_id',m.id,'deliverable_id',d.id);end if;insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(m.client_organization_id,a,'USER','delivery.decided','deliverable',d.id::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(m.client_organization_id,'mission',m.id::text,case when r->>'outcome'='DELIVERY_ACCEPTED'then'DeliveryAcceptedV1'else'DeliveryRejectedV1'end,p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(m.client_organization_id,'delivery.accept.'||d.id::text,p_idempotency_key,r);return r;end$$;

create function public.create_contract_amendment(p_contract_id uuid,p_reason text,p_scope_delta jsonb,p_price_delta_minor bigint,p_deadline_delta_days integer,p_deliverables_delta jsonb,p_commission_rule_snapshot jsonb,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();c public.contracts%rowtype;v uuid;h text;r jsonb;cr uuid;am uuid;n integer;begin select * into c from public.contracts where id=p_contract_id;if a is null or not found or c.status not in('ACTIVE','AMENDED')or not private.contract_party_access(c.id,a)then raise exception 'AMENDMENT_CREATE_DENIED' using errcode='42501';end if;if length(btrim(coalesce(p_reason,'')))not between 3 and 2000 or jsonb_typeof(p_scope_delta)<>'object'or jsonb_typeof(p_deliverables_delta)<>'array'or jsonb_typeof(p_commission_rule_snapshot)<>'object'then raise exception 'INVALID_AMENDMENT' using errcode='22023';end if;select id into v from public.contract_versions where contract_id=c.id and version=c.current_version;h:=private.canonical_request_hash(jsonb_build_object('contract',c.id,'reason',p_reason,'scope',p_scope_delta,'price_delta_minor',p_price_delta_minor,'deadline_delta_days',p_deadline_delta_days,'deliverables',p_deliverables_delta,'commission',p_commission_rule_snapshot));r:=private.begin_contract_command(c.client_organization_id,'contract.amendment.create',p_idempotency_key,h,a);if r is not null then return r;end if;insert into public.change_requests(contract_id,requested_by,reason,scope_delta)values(c.id,a,p_reason,p_scope_delta)returning id into cr;select coalesce(max(amendment_number),0)+1 into n from public.contract_amendments where contract_id=c.id;insert into public.contract_amendments(contract_id,change_request_id,base_contract_version_id,amendment_number,price_delta_minor,deadline_delta_days,deliverables_delta,commission_rule_snapshot,content_hash,created_by)values(c.id,cr,v,n,p_price_delta_minor,p_deadline_delta_days,p_deliverables_delta,p_commission_rule_snapshot,h,a)returning id into am;r:=jsonb_build_object('outcome','CONTRACT_AMENDMENT_DRAFTED','contract_id',c.id,'change_request_id',cr,'amendment_id',am,'amendment_number',n,'base_contract_version_id',v);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(c.client_organization_id,a,'USER','contract.amendment_drafted','contract_amendment',am::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(c.client_organization_id,'contract',c.id::text,'ContractAmendmentDraftedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(c.client_organization_id,'contract.amendment.create',p_idempotency_key,r);return r;end$$;

alter table public.contracts enable row level security;alter table public.contract_versions enable row level security;alter table public.contract_parties enable row level security;alter table public.contract_items enable row level security;alter table public.contract_signatures enable row level security;alter table public.change_requests enable row level security;alter table public.contract_amendments enable row level security;alter table public.missions enable row level security;alter table public.mission_milestones enable row level security;alter table public.service_checklist_templates enable row level security;alter table public.mission_checklist_items enable row level security;alter table public.deliverables enable row level security;alter table public.delivery_versions enable row level security;alter table public.delivery_proofs enable row level security;alter table public.acceptance_checklists enable row level security;
create policy contracts_party_read on public.contracts for select to authenticated using(private.contract_party_access(id));
create policy contract_versions_party_read on public.contract_versions for select to authenticated using(private.contract_party_access(contract_id));
create policy contract_parties_party_read on public.contract_parties for select to authenticated using(private.contract_party_access((select v.contract_id from public.contract_versions v where v.id=contract_version_id)));
create policy contract_items_party_read on public.contract_items for select to authenticated using(private.contract_party_access((select v.contract_id from public.contract_versions v where v.id=contract_version_id)));
create policy contract_signatures_party_read on public.contract_signatures for select to authenticated using(private.contract_party_access(contract_id));
create policy change_requests_party_read on public.change_requests for select to authenticated using(private.contract_party_access(contract_id));
create policy amendments_party_read on public.contract_amendments for select to authenticated using(private.contract_party_access(contract_id));
create policy missions_party_read on public.missions for select to authenticated using(private.mission_party_access(id));
create policy milestones_party_read on public.mission_milestones for select to authenticated using(private.mission_party_access(mission_id));
create policy checklist_party_read on public.mission_checklist_items for select to authenticated using(private.mission_party_access(mission_id));
create policy deliverables_party_read on public.deliverables for select to authenticated using(private.mission_party_access(mission_id));
create policy delivery_versions_party_read on public.delivery_versions for select to authenticated using(private.mission_party_access((select d.mission_id from public.deliverables d where d.id=deliverable_id)));
create policy delivery_proofs_party_read on public.delivery_proofs for select to authenticated using(private.mission_party_access((select d.mission_id from public.delivery_versions v join public.deliverables d on d.id=v.deliverable_id where v.id=delivery_version_id)));
create policy acceptance_party_read on public.acceptance_checklists for select to authenticated using(private.mission_party_access(mission_id));
revoke all on public.contracts,public.contract_versions,public.contract_parties,public.contract_items,public.contract_signatures,public.change_requests,public.contract_amendments,public.missions,public.mission_milestones,public.service_checklist_templates,public.mission_checklist_items,public.deliverables,public.delivery_versions,public.delivery_proofs,public.acceptance_checklists from public,anon,authenticated;
grant select on public.contracts,public.contract_versions,public.contract_parties,public.contract_items,public.contract_signatures,public.change_requests,public.contract_amendments,public.missions,public.mission_milestones,public.mission_checklist_items,public.deliverables,public.delivery_versions,public.delivery_proofs,public.acceptance_checklists to authenticated;
revoke all on function private.contract_party_access(uuid,uuid),private.mission_party_access(uuid,uuid),private.bind_selected_quote_version(),private.begin_contract_command(uuid,text,text,text,uuid),private.finish_contract_command(uuid,text,text,jsonb)from public,anon,authenticated,service_role;
grant execute on function private.contract_party_access(uuid,uuid),private.mission_party_access(uuid,uuid)to authenticated;
revoke all on function public.generate_contract(uuid,uuid,jsonb,jsonb,jsonb,bigint,text,jsonb,jsonb,jsonb,text,text,uuid),public.submit_contract_for_signature(uuid,integer,text,uuid),public.sign_contract(uuid,uuid,uuid,text,text,jsonb,text,uuid),public.create_mission(uuid,uuid,jsonb,jsonb,jsonb,text,uuid),public.submit_delivery(uuid,text,jsonb,jsonb,text,uuid),public.accept_delivery(uuid,jsonb,text,uuid),public.create_contract_amendment(uuid,text,jsonb,bigint,integer,jsonb,jsonb,text,uuid)from public,anon,authenticated,service_role;
grant execute on function public.generate_contract(uuid,uuid,jsonb,jsonb,jsonb,bigint,text,jsonb,jsonb,jsonb,text,text,uuid),public.submit_contract_for_signature(uuid,integer,text,uuid),public.sign_contract(uuid,uuid,uuid,text,text,jsonb,text,uuid),public.create_mission(uuid,uuid,jsonb,jsonb,jsonb,text,uuid),public.submit_delivery(uuid,text,jsonb,jsonb,text,uuid),public.accept_delivery(uuid,jsonb,text,uuid),public.create_contract_amendment(uuid,text,jsonb,bigint,integer,jsonb,jsonb,text,uuid)to authenticated;
create index contracts_client_status_idx on public.contracts(client_organization_id,status,created_at desc);create index contracts_provider_status_idx on public.contracts(provider_organization_id,status,created_at desc);create index missions_client_status_idx on public.missions(client_organization_id,status,created_at desc);create index missions_provider_status_idx on public.missions(provider_organization_id,status,created_at desc);create index milestones_due_idx on public.mission_milestones(mission_id,status,due_at);create index delivery_versions_latest_idx on public.delivery_versions(deliverable_id,version desc);
